"""Emit Lift04 LOD2 shoulder fragments while removing only the central road bed."""
from pathlib import Path
import hashlib,sys
import numpy as np
r,output=map(Path,sys.argv[1:])
assert hashlib.sha256((r/'movable-skin/LiftBridge04_LOD2 Mesh.Geometry').read_bytes()).hexdigest()=='ab81a0e0cdd6345fd8e80cdbad7c52b947fc7281aca1c1c37f986af0d49e863d'
d=np.load(r/'lift04-main-2-0.npz');v,f,c=d['positions'],d['indices'],d['component']
selected=[846,847,868,869,1156,1157,1158,1159,1160,1161,1568,1569,1570,1571]
edges=[];extra=[];fragments=[]
for ordinal in selected:
 face=f[ordinal];p=v[face];assert (p[:,1]==9.800049).all() and set(p[:,0])=={-5,5}
 assert c[face[0]] in (83,85,165)
 indices=[]
 for side in (-1,1):
  boundary=side*4;poly=[]
  for a,b in zip(np.eye(3),np.roll(np.eye(3),-1,axis=0)):
   xa,xb=a@p[:,0],b@p[:,0];ina=side*xa>=4;inb=side*xb>=4
   if ina:poly.append(a)
   if ina!=inb:poly.append(a+(b-a)*((boundary-xa)/(xb-xa)))
  polygon=[]
  for bary in poly:
   nonzero=np.flatnonzero(abs(bary)>1e-10)
   if len(nonzero)==1:polygon.append(int(face[nonzero[0]]))
   else:
    assert len(nonzero)==2;a,b=map(int,nonzero);t=float(np.float32(bary[b]));polygon.append(len(v)+len(edges));edges.append((int(face[a]),int(face[b]),t,side));extra.append(p[a]+(p[b]-p[a])*t)
  for i in range(1,len(polygon)-1):indices += [polygon[0],polygon[i],polygon[i+1]]
 fragments.append((ordinal,indices))
allv=np.concatenate((v,np.array(extra)));ff=np.array([ids[i:i+3] for _,ids in fragments for i in range(0,len(ids),3)])
q=allv[ff];area=np.cross(q[:,1]-q[:,0],q[:,2]-q[:,0])[:,1].sum()/2
assert abs(area - 2*(2*79.84961+32))<1e-4
assert len(edges)==56 and len(ff)==42
for delta in (-.5,0,2,8):
 moved=allv.copy();moved[:len(v),0]+=np.sign(v[:,0])*delta
 for i,e in enumerate(edges):moved[len(v)+i,0]+=e[3]*delta
 q=moved[ff];assert np.all(np.cross(q[:,1]-q[:,0],q[:,2]-q[:,0])[:,1]>0)
 assert abs(np.cross(q[:,1]-q[:,0],q[:,2]-q[:,0])[:,1].sum()/2-area)<1e-8
np.savez(r/'lift04-far-shoulders.npz',positions=allv,indices=ff)
lines=['// Measured LiftBridge04 LOD2 road/shoulder separation; generated by Lift04FarShoulders.py.','using System;','using System.Linq;','using UnityEngine;','','namespace BridgeBuilder.Bridges;','','internal static class Lift04FarShoulders','{','    internal static MovableStructureModel.Plan Apply(MovableStructureModel.Plan plan, float delta)','    {','        const int count = 3212;','        if (plan.SourcePositions.Length != count || plan.SourceIndices.Length != 1 || plan.SourceIndices[0].Length != 5208 || plan.InteriorVertices.Length != 0)','            throw new InvalidOperationException("Lift04 far shoulders require the recorded edge-only structure plan.");','        var positions = new Vector3[count];','        Array.Copy(plan.Positions, positions, count);','        var offset = plan.AddedVertices.Length;','        var x = new float[offset + Edges.Length];','        for (var i = 0; i < offset; i++) x[i] = plan.Positions[count + i].x;','        for (var i = 0; i < Edges.Length; i++)','        {','            var edge = Edges[i];','            x[offset + i] = Mathf.LerpUnclamped(plan.SourcePositions[edge.A].x, plan.SourcePositions[edge.B].x, edge.Fraction) + Signs[i] * delta;','        }','        foreach (var face in SourceFaces)','        {','            var indices = plan.SourceIndices[0]; var i = face.Triangle * 3;','            if (indices[i] != face.A || indices[i+1] != face.B || indices[i+2] != face.C)','                throw new InvalidOperationException("Lift04 far road source topology changed.");','        }','        var fragments = Fragments.Select(f => new MovableStructureModel.Fragment(0, f.Triangle,','            f.Indices.Select(i => i < count ? i : i + offset).ToArray())).ToArray();','        return new MovableStructureModel.Plan(plan.SourcePositions, positions, plan.SourceIndices,','            plan.RemoveTriangles, plan.AddedVertices.Concat(Edges).ToArray(), plan.Fragments.Concat(fragments).ToArray(), constructedX: x);','    }','    private static readonly (int Triangle, int A, int B, int C)[] SourceFaces =','    {']
lines += [f'        ({i}, {f[i,0]}, {f[i,1]}, {f[i,2]}),' for i in selected]
lines += ['    };','    private static readonly MovableStructureModel.EdgeVertex[] Edges =','    {']
lines += [f'        new({a}, {b}, {t:.9g}f),' for a,b,t,_ in edges]
lines += ['    };','    private static readonly float[] Signs = { '+', '.join(str(e[3])+'f' for e in edges)+' };','    private static readonly MovableStructureModel.Fragment[] Fragments =','    {']
lines += ['        new(0, '+str(i)+', '+', '.join(map(str,ids))+'),' for i,ids in fragments]
lines += ['    };','}',''];output.write_text('\n'.join(lines),encoding='utf-8')
print('PASS 14 source tops -> 42 shoulder triangles, 56 interpolated vertices; central road removed, shoulder area and winding retained at four widths')
